 kid:{"id":"kid","no":104,"name":"基德（電磁炮模式）","title":"磁力人","types":["超能"],"image":"assets/chars/kid.webp?v=26","avatar":"assets/chars/kid_face.webp?v=26","ultimateBg":"assets/chars/kid.webp?v=26","scale":1.15,"worldScale":0.95,"maxHp":1450,"baseSpeed":105,"ai":"aggressive","desc":"「超新星」之一，吸附金屬的磁力人。把整座廢鐵堆組成巨大的電磁炮，一擊撼動天地。","skills":[{"name":"磁氣機械臂","type":"attack","pp":12,"maxPP":12,"power":60,"accuracy":100,"anima":"kaifu","desc":"用磁力組成的機械臂強力攻擊對手 3 次，並回復自身 3～5% 體力。","tags":[["連擊","red"],["回復","green"]],"effect":{"multiHitNormal":[3,3],"perHitPower":60,"healRange":[0.03,0.05]}},{"name":"磁氣魔人","type":"support","pp":5,"maxPP":5,"power":0,"accuracy":100,"anima":"shuryu","desc":"攻擊 +2、防禦 +2、速度 -1，接下來 2 回合傷害變為 2～5 倍。","tags":[["強化","gold"]],"effect":{"selfBuffAtk":2,"selfBuffDef":2,"selfBuffSpd":-1,"damageMultTurns":2,"damageMultRange":[2,5]}},{"name":"電磁砲","type":"attack","pp":4,"maxPP":4,"power":100,"accuracy":100,"anima":"raimei","desc":"對敵人造成 5～15 倍傷害，有 3～5% 機率直接秒殺。","tags":[["秒殺","red"]],"effect":{"randomMultiplierRange":[5,15],"executeChanceRange":[0.03,0.05]}},{"name":"磁氣震動","type":"support","pp":4,"maxPP":4,"power":0,"accuracy":100,"anima":"raimei","desc":"使對手 1 回合無法攻擊，並隨機讓自己的一個技能次數 +1（第五技能除外）。","tags":[["麻痺","gray"],["次數","blue"]],"effect":{"skipAttackTurns":1,"ccKind":"paralyze","randomSelfPPUp":1}},{"name":"賦極","type":"support","pp":2,"maxPP":2,"power":0,"accuracy":100,"anima":"karyu","ultimate":true,"desc":"對手防禦 -2（持續 2 回合），自身全能力 +1，接下來 2 回合傷害 +30%，消除對手的能力提升，並有 25% 機率使對手麻痺。","tags":[["破防","red"],["清強化","blue"],["麻痺","gray"]],"effect":{"enemyDefDownTemp":[2,2],"statUpAll":1,"clearBuffs":true,"paralyzeChance":0.25,"paralyzeTurns":1,"damageMultTurns":2,"damageMultValue":1.3}}]},
