 imu:{"id":"imu","no":999,"noText":"???","name":"伊姆","title":"世界之王","types":["闇"],"image":"assets/chars/imu.webp?v=26","avatar":"assets/chars/imu_face.webp?v=26","ultimateBg":"assets/chars/imu.webp?v=26","scale":0.65,"worldScale":1,"maxHp":2000,"baseSpeed":115,"ai":"aggressive","skinSkills":[0,1,3,4],"desc":"坐在瑪莉喬亞「空白王座」上的世界之王，真實身分籠罩在黑影之中。未裝備皮膚時只能使用「不死之身」。","skills":[{"name":"黑轉支配","type":"support","pp":1,"maxPP":1,"power":0,"accuracy":100,"anima":"naraku","desc":"直接把對手場上的角色變成自己的部下；若自身隊伍已滿，則封印對手場上角色 3 回合。","tags":[["支配","red"]],"effect":{"dominate":true,"noRestore":true}},{"name":"世界之王","type":"attack","pp":1,"maxPP":1,"power":80,"accuracy":100,"anima":"raimei","desc":"90% 機率直接秒殺對手。","tags":[["秒殺","red"]],"effect":{"executeChance":0.9,"noRestore":true}},{"name":"不死之身","type":"support","pp":3,"maxPP":3,"power":0,"accuracy":100,"anima":"cook","desc":"3 回合內，每回合結束時體力回復至 100%。","tags":[["全回復","green"]],"effect":{"fullRestoreTurns":3}},{"name":"魔氣變化","type":"attack","pp":8,"maxPP":8,"power":100,"accuracy":100,"anima":"naraku","desc":"魔氣化為各種武器，每次隨機施展一種：天罰劍（6～10 倍傷害）、日食爆擊（扣除 20% 最大體力）、憤怒劍（5～10 連擊）、怨魔劍（3 連擊並吸血 50%）、虛無劍（扣除目前體力的 15～25%）。","tags":[["隨機","gold"]],"effect":{"variants":[{"name":"天罰劍","power":100,"effect":{"randomMultiplierRange":[6,10]}},{"name":"日食爆擊","power":0,"effect":{"fixedLightHits":[1,0.2]}},{"name":"憤怒劍","power":40,"effect":{"multiHitNormal":[5,10],"perHitPower":40}},{"name":"怨魔劍","power":60,"effect":{"multiHitNormal":[3,3],"perHitPower":60,"lifesteal":0.5}},{"name":"虛無劍","power":0,"effect":{"randomPercentHits":[1,0.15,0.25,true]}}]}},{"name":"最初的20人","type":"support","pp":1,"maxPP":1,"power":0,"accuracy":100,"anima":"awaken","ultimate":true,"desc":"獲得 20 條命（倒下時以全滿體力復活），只能使用一次，藥水無法補充次數。","tags":[["復活","gold"]],"effect":{"extraLives":20,"noRestore":true}}]},
 moria:{"id":"moria","no":22,"name":"月光·莫莉亞","title":"七武海","types":["闇"],"image":"assets/chars/moria.webp?v=32","avatar":"assets/chars/moria_face.webp?v=32","ultimateBg":"assets/chars/moria.webp?v=32","scale":1,"worldScale":1,"maxHp":1800,"baseSpeed":85,"ai":"aggressive","desc":"前王下七武海，影子果實能力者。操控搶來的影子與殭屍大軍，坐鎮恐怖三桅帆船。","skills":[{"name":"影法師","type":"attack","pp":12,"maxPP":12,"power":45,"accuracy":100,"anima":"shigan","desc":"召喚 3～5 個影子分身攻擊 3～5 次；對手受到的傷害轉為莫莉亞的護盾（護盾只維持 1 回合）。","tags":[["連擊","red"],["護盾","blue"]],"effect":{"multiHitNormal":[3,5],"perHitPower":45,"shieldFromDamage":1}},{"name":"影武者","type":"support","pp":5,"maxPP":5,"power":0,"accuracy":100,"anima":"cook","desc":"讓影子替身擋下對手的下一次攻擊，並回復自身 10% 體力。","tags":[["閃避","blue"],["回復","green"]],"effect":{"dodgeTurns":1,"healRatio":0.1}},{"name":"角刀影","type":"attack","pp":6,"maxPP":6,"power":130,"accuracy":100,"anima":"sandslash","desc":"影子化為巨大的影之蜥蜴，以尖角刺穿對手；清除對手的能力提升，並有 50% 機率使對手虛弱。","tags":[["清強化","blue"],["虛弱","gray"]],"effect":{"clearBuffs":true,"weakChance":0.5,"weakTurns":1}},{"name":"影箱","type":"attack","pp":4,"maxPP":4,"power":30,"accuracy":100,"anima":"naraku","desc":"隨機發動其中一種：「對手 2 回合無法攻擊」或「普通攻擊對手 5～10 次」。","tags":[["隨機","gold"]],"effect":{"variants":[{"name":"影箱・封印","power":0,"effect":{"skipAttackTurns":2,"ccKind":"fear","noDamage":true}},{"name":"影箱・連擊","power":30,"effect":{"multiHitNormal":[5,10],"perHitPower":30}}]}},{"name":"影子集合地","type":"support","pp":1,"maxPP":1,"power":0,"accuracy":100,"anima":"awaken","ultimate":true,"desc":"強制剪下周圍所有人的影子吸入體內：體力上限與體力增加等同對手目前的體力（最多自身最大體力的 50%），對手受到 100～1000 點隨機傷害，自身防禦 +2，身形巨大化。","tags":[["吸收","gold"],["巨大化","red"]],"effect":{"gainTargetHp":true,"randomFlatDamage":[100,1000],"selfBuffDef":2,"growScale":1.3,"gainTargetHpCap":0.5}}]},
